def tree_diameter(nodes: list) -> int:
    if not nodes or nodes[0] is None:
        return 0
    max_diam = 0
    def height(idx):
        nonlocal max_diam
        if idx >= len(nodes) or nodes[idx] is None:
            return 0
        lh = height(2 * idx + 1)
        rh = height(2 * idx + 2)
        max_diam = max(max_diam, lh + rh + 1)
        return 1 + max(lh, rh)
    height(0)
    return max_diam
